<?php require_once __DIR__.'/includes/bootstrap.php';require_login();if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$old=(string)($_POST['password_lama']??'');$new=(string)($_POST['password_baru']??'');$confirm=(string)($_POST['konfirmasi']??'');$q=$pdo->prepare('SELECT password FROM users WHERE id_user=?');$q->execute([current_user()['id_user']]);$hash=$q->fetchColumn();if(!$hash||!password_verify($old,$hash)){flash('danger','Password lama tidak sesuai.');}elseif(strlen($new)<10||$new!==$confirm){flash('danger','Password baru minimal 10 karakter dan konfirmasi harus sama.');}else{$s=$pdo->prepare('UPDATE users SET password=? WHERE id_user=?');$s->execute([password_hash($new,PASSWORD_DEFAULT),current_user()['id_user']]);flash('success','Password berhasil diperbarui.');}redirect('/account.php');}page_header('Pengaturan Akun');?><div class="card p-4" style="max-width:620px"><p class="text-secondary">Ganti password akun SIPACAK yang sedang digunakan. Password tidak pernah ditampilkan kembali.</p><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><div class="mb-3"><label class="form-label">Password Lama</label><input type="password" class="form-control" name="password_lama" required autocomplete="current-password"></div><div class="mb-3"><label class="form-label">Password Baru</label><input type="password" class="form-control" name="password_baru" minlength="10" required autocomplete="new-password"></div><div class="mb-3"><label class="form-label">Konfirmasi Password Baru</label><input type="password" class="form-control" name="konfirmasi" minlength="10" required autocomplete="new-password"></div><button class="btn btn-primary">Simpan Password</button></form></div><?php page_footer();
